-- Casa Vina menu — data restore
--
-- Snapshot taken 2026-10-04 from project nylufogmuromxuqvsvkx, which was deleted on
-- 2026-10-15. This is the only copy of the menu data.
--
-- Run AFTER the schema migrations in supabase/migrations/ have been applied to
-- the replacement project, and BEFORE importing anything through the admin
-- panel (an Excel import deletes every category and dish first).
--
-- Original ids are preserved so dishes keep their categories. Photo URLs still
-- point at the deleted project's storage and will not load until the images are
-- re-uploaded; see the note at the end of this file.

begin;

-- Refuse to run on a database that already holds a menu, rather than
-- duplicating or colliding with it.
do $$
begin
  if (select count(*) from public.categories) > 0
     or (select count(*) from public.dishes) > 0 then
    raise exception 'categories/dishes are not empty — clear them first or restore into a fresh project';
  end if;
end $$;

-- Categories (13)

-- Dishes (108)

commit;

-- Photos: the 80 image_url values above reference the deleted project's
-- storage bucket and will 404. Once the images have been re-uploaded to the
-- replacement project's dish-images bucket under the same file names, repoint
-- the rows in one statement:
--
--   update public.dishes
--   set image_url = replace(image_url, 'nylufogmuromxuqvsvkx', '<new-project-ref>')
--   where image_url like '%nylufogmuromxuqvsvkx%';
--
-- If the originals are gone, clear them instead so the menu falls back to its
-- text-only layout rather than showing broken frames:
--
--   update public.dishes set image_url = null;
